import { invoke } from "@tauri-apps/api/core";
import { loadBrowserSettings } from "./browserSettings";
import type {
  BrowserSessionSummary,
  BrowserState,
  CreateBrowserRequest,
  LogicalRect,
} from "./types";

const browserLifecycleQueues = new Map<string, Promise<void>>();

function enqueueBrowserLifecycle(browserId: string, operation: () => Promise<void>): Promise<void> {
  const previous = browserLifecycleQueues.get(browserId) ?? Promise.resolve();
  const next = previous.catch(() => undefined).then(operation);
  browserLifecycleQueues.set(browserId, next);

  const clearIfCurrent = () => {
    if (browserLifecycleQueues.get(browserId) === next) {
      browserLifecycleQueues.delete(browserId);
    }
  };
  void next.then(clearIfCurrent, clearIfCurrent);

  return next;
}

async function applyConfiguredZoom(state: BrowserState): Promise<BrowserState> {
  const zoomFactor = loadBrowserSettings().defaultZoom / 100;
  if (Math.abs((state.zoomFactor || 1) - zoomFactor) < 0.001) return state;
  try {
    const applied = await setBrowserZoom(state.browserId, zoomFactor);
    return { ...state, zoomFactor: applied };
  } catch {
    return state;
  }
}

export async function createBrowser(request: CreateBrowserRequest): Promise<BrowserState> {
  const state = await invoke<BrowserState>("cmd_browser_create", { request });
  return applyConfiguredZoom(state);
}

export async function restoreBrowser(request: {
  browserId: string;
  url: string;
  visible?: boolean;
}): Promise<BrowserState> {
  const state = await invoke<BrowserState>("cmd_browser_restore", { request });
  return applyConfiguredZoom(state);
}

