function firstLeafId(node: PaneNode): string {
  let current = node;
  while (current.type === "split") current = current.first;
  return current.leafId;
}

function firstTabGroupId(node: TabGroupLayoutNode | null): string | null {
  if (!node) return null;
  let current = node;
  while (current.type === "split") current = current.first;
  return current.groupId;
}

