<body>
<textarea id="editor" placeholder="Type markdown here..." autofocus># Markdown Scratchpad

Welcome to your scratchpad. Start typing markdown on the left to see live preview on the right.

- **Bold** and *Italic* text
- \`inline code\`
- [Links](https://github.com)
- Lists and headings

\`\`\`js
console.log("Hello, world!");
\`\`\`
</textarea>
<div id="preview"></div>
<script>
function renderMarkdown(src) {
  var html = src
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  var lines = html.split("\\n");
  var output = [];
  var inList = false;
  var inCodeBlock = false;
  var codeBuffer = [];

  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];

    if (line.trim().startsWith("\`\`\`")) {
      if (inCodeBlock) {
        output.push("<pre><code>" + codeBuffer.join("\\n") + "</code></pre>");
        codeBuffer = [];
        inCodeBlock = false;
      } else {
        if (inList) {
          output.push("</ul>");
          inList = false;
        }
        inCodeBlock = true;
        codeBuffer = [];
      }
      continue;
    }

    if (inCodeBlock) {
      codeBuffer.push(line);
      continue;
    }

    if (/^### (.*)$/.test(line)) {
      if (inList) { output.push("</ul>"); inList = false; }
      output.push("<h3>" + formatInline(RegExp.$1) + "</h3>");
      continue;
    }
    if (/^## (.*)$/.test(line)) {
      if (inList) { output.push("</ul>"); inList = false; }
      output.push("<h2>" + formatInline(RegExp.$1) + "</h2>");
      continue;
    }
    if (/^# (.*)$/.test(line)) {
      if (inList) { output.push("</ul>"); inList = false; }
      output.push("<h1>" + formatInline(RegExp.$1) + "</h1>");
      continue;
    }

    if (/^[-*] (.*)$/.test(line)) {
      if (!inList) { output.push("<ul>"); inList = true; }
      output.push("<li>" + formatInline(RegExp.$1) + "</li>");
      continue;
    } else if (inList) {
      output.push("</ul>");
      inList = false;
    }

    if (line.trim() === "") {
      continue;
    }

    output.push("<p>" + formatInline(line) + "</p>");
  }

  if (inCodeBlock) {
    output.push("<pre><code>" + codeBuffer.join("\\n") + "</code></pre>");
  }
  if (inList) {
    output.push("</ul>");
  }

  return output.join("");
}

function formatInline(text) {
  return text
    .replace(/\\*\\*(.+?)\\*\\*/g, "<strong>$1</strong>")
    .replace(/\\*(.+?)\\*/g, "<em>$1</em>")
    .replace(/\`([^\\\`]+)\`/g, "<code>$1</code>")
    .replace(/\\[([^\\]]+)\\]\\(([^)]+)\\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
}

var editor = document.getElementById("editor");
var preview = document.getElementById("preview");
function update() { preview.innerHTML = renderMarkdown(editor.value); }
editor.addEventListener("input", update);
update();
</script>
